import React, { useMemo, useState, useEffect } from 'react';
import { ComposedChart, Line, Area, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, XAxis, YAxis } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Flame, Wallet, CreditCard, Target, Zap, Microscope, FileText, ChevronDown, AlignLeft, GitFork, UserCircle, PieChart as PieChartIcon, TrendingUp, AlertCircle, Check, Plus, Rocket, BarChart3, Clock, Shield, Handshake, Gauge, ArrowUp, CalendarClock, CheckCircle2 } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string, params?: any) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
  userName?: string;
  isPrivacyMode?: boolean;
}

const COLORS = ['#3b82f6', '#f97316', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const CircularProgress = ({ percentage, color }: { percentage: number, color: string }) => {
  const radius = 10; // Small radius for the mini charts
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (Math.min(percentage, 100) / 100) * circumference;

  return (
    <div className="relative w-8 h-8 flex items-center justify-center">
      <svg className="w-full h-full transform -rotate-90">
        {/* Background Circle */}
        <circle cx="16" cy="16" r={radius} stroke="#1e293b" strokeWidth="3" fill="transparent" />
        {/* Progress Circle */}
        <circle 
          cx="16" 
          cy="16" 
          r={radius} 
          stroke={color} 
          strokeWidth="3" 
          fill="transparent" 
          strokeDasharray={circumference} 
          strokeDashoffset={strokeDashoffset} 
          strokeLinecap="round" 
        />
      </svg>
    </div>
  );
};

const CreditScoreGauge = () => {
    const score = 792;
    const max = 850;
    const min = 300;
    const range = max - min;
    const percentage = Math.min(Math.max((score - min) / range, 0), 1) * 100;

    // SVG Geometry for a 260-degree arc gauge
    const size = 120;
    const strokeWidth = 8;
    const center = size / 2;
    const radius = (size - strokeWidth) / 2 - 10;
    const startAngle = 140; // degrees
    const endAngle = 400; // degrees (140 + 260)
    const totalAngle = 260;

    const angleToRad = (angle: number) => (angle * Math.PI) / 180;

    const calculatePath = (percent: number) => {
        const start = angleToRad(startAngle);
        const end = angleToRad(startAngle + (percent / 100) * totalAngle);

        const x1 = center + radius * Math.cos(start);
        const y1 = center + radius * Math.sin(start);
        const x2 = center + radius * Math.cos(end);
        const y2 = center + radius * Math.sin(end);

        const largeArc = (percent / 100) * totalAngle > 180 ? 1 : 0;

        // If 0%, draw nothing to avoid artifact
        if (percent <= 0) return "";

        return `M ${x1} ${y1} A ${radius} ${radius} 0 ${largeArc} 1 ${x2} ${y2}`;
    };

    return (
        <div className="flex flex-col items-center justify-center relative w-full h-full">
            <div className="relative w-24 h-24 sm:w-28 sm:h-28 flex items-center justify-center">
                <svg width="100%" height="100%" viewBox={`0 0 ${size} ${size}`}>
                    <defs>
                        <linearGradient id="gaugeGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                            <stop offset="0%" stopColor="#ef4444" />
                            <stop offset="50%" stopColor="#f59e0b" />
                            <stop offset="100%" stopColor="#10b981" />
                        </linearGradient>
                        <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
                            <feGaussianBlur stdDeviation="3" result="blur" />
                            <feComposite in="SourceGraphic" in2="blur" operator="over" />
                        </filter>
                    </defs>
                    {/* Track */}
                    <path 
                        d={calculatePath(100)} 
                        fill="none" 
                        stroke="#1e293b" 
                        strokeWidth={strokeWidth} 
                        strokeLinecap="round" 
                    />
                    {/* Progress */}
                    <path 
                        d={calculatePath(percentage)} 
                        fill="none" 
                        stroke="url(#gaugeGradient)" 
                        strokeWidth={strokeWidth} 
                        strokeLinecap="round" 
                        filter="url(#glow)"
                        className="transition-all duration-1000 ease-out"
                    />
                </svg>

                <div className="absolute inset-0 flex flex-col items-center justify-center pt-2">
                    <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest mb-0.5">FICO</span>
                    <div className="text-3xl font-black text-white tracking-tighter leading-none">{score}</div>
                    <div className="text-[8px] font-bold text-emerald-400 uppercase tracking-widest mt-1 bg-emerald-500/10 px-1.5 py-0.5 rounded border border-emerald-500/20">Excellent</div>
                </div>
            </div>

            <div className="absolute -bottom-2 flex items-center gap-1 bg-slate-900/80 px-2 py-1 rounded-lg border border-white/5 shadow-lg backdrop-blur-sm">
                <ArrowUp className="w-2.5 h-2.5 text-emerald-500" />
                <span className="text-[8px] text-slate-400 font-bold">+5pts</span>
            </div>
        </div>
    );
};

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly',
    userName = 'Pilot',
    isPrivacyMode = false
}) => {
  const [spendingComparison, setSpendingComparison] = useState<'year' | 'month'>('year');
  const [activeMenu, setActiveMenu] = useState<string | null>(null);
  const [showScanConfirm, setShowScanConfirm] = useState(false);

  // Close menus on click outside
  useEffect(() => {
      const handleClickOutside = () => setActiveMenu(null);
      document.addEventListener('click', handleClickOutside);
      return () => document.removeEventListener('click', handleClickOutside);
  }, []);

  const toggleMenu = (e: React.MouseEvent, menuId: string) => {
      e.stopPropagation();
      setActiveMenu(activeMenu === menuId ? null : menuId);
  };

  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const dayName = today.toLocaleDateString('en-US', { weekday: 'long' });

  // Capture timestamp on mount/render for "Last Updated"
  const lastUpdated = useMemo(() => new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), []);

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const creditCardDebt = useMemo(() => {
      return accounts
        .filter(a => a.type === 'Credit Card' && a.balance < 0)
        .reduce((acc, curr) => acc + Math.abs(curr.balance), 0);
  }, [accounts]);

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const currentDay = today.getDate();
    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);

    return { currentDailyAvg };
  }, [transactions, currentMonth, currentYear]);

  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth && 
        new Date(t.date).getFullYear() === currentYear
    );

    const total = expenses.reduce((acc, t) => acc + t.amount, 0);
    const catMap: Record<string, number> = {};

    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

    if (chartData.length === 0) {
        return { chartData: [], total: 0, isEmpty: true, topCategory: null };
    }

    return { chartData, total, isEmpty: false, topCategory: chartData[0] };
  }, [transactions, currentMonth, currentYear]);

  const lineChartData = useMemo(() => {
    const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const data = [];

    const getDailySpend = (month: number, year: number) => {
        const daily = new Array(32).fill(0);
        transactions.forEach(t => {
            const d = new Date(t.date);
            if (t.type === TransactionType.EXPENSE && d.getMonth() === month && d.getFullYear() === year) {
                daily[d.getDate()] += t.amount;
            }
        });
        for (let i = 1; i < daily.length; i++) daily[i] += daily[i-1];
        return daily;
    };

    const currentMonthData = getDailySpend(currentMonth, currentYear);
    let comparisonData: number[] = [];
    if (spendingComparison === 'year') {
        comparisonData = getDailySpend(currentMonth, currentYear - 1);
    } else {
        let prevMonth = currentMonth - 1;
        let prevYear = currentYear;
        if (prevMonth < 0) { prevMonth = 11; prevYear = currentYear - 1; }
        comparisonData = getDailySpend(prevMonth, prevYear);
    }

    for (let i = 1; i <= daysInCurrentMonth; i++) {
        data.push({
            day: i,
            ThisMonth: currentMonthData[i],
            Comparison: comparisonData[i] 
        });
    }
    return data;
  }, [transactions, currentMonth, currentYear, spendingComparison]);

  const { paidBills, upcomingBills } = useMemo(() => {
      const subs = transactions.filter(t => t.category === Category.SUBSCRIPTION);
      const unique = new Map<string, Transaction>();

      // Get latest transaction for each subscription merchant
      subs.forEach(t => {
          const key = t.merchant.toLowerCase();
          const existing = unique.get(key);
          if (!existing || new Date(t.date) > new Date(existing.date)) {
              unique.set(key, t);
          }
      });

      const paid: Transaction[] = [];
      const upcoming: { merchant: string; amount: number; date: Date; daysLeft: number }[] = [];

      const now = new Date();

      unique.forEach(t => {
          const tDate = new Date(t.date);
          // Check if paid this month
          if (tDate.getMonth() === currentMonth && tDate.getFullYear() === currentYear) {
              paid.push(t);
          } else {
              // Estimate next due date (same day of current month)
              let due = new Date(currentYear, currentMonth, tDate.getDate());
              const diffTime = due.getTime() - now.getTime();
              const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

              upcoming.push({
                  merchant: t.merchant,
                  amount: t.amount,
                  date: due,
                  daysLeft: diffDays
              });
          }
      });

      // Sort
      paid.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      upcoming.sort((a, b) => a.daysLeft - b.daysLeft);

      return { paidBills: paid.slice(0, 4), upcomingBills: upcoming.slice(0, 4) };
  }, [transactions, currentMonth, currentYear]);

  const recentTransactions = useMemo(() => {
      return transactions.slice(0, 4);
  }, [transactions]);

  const goalMetrics = useMemo(() => {
      const limitVal = Number(spendingLimit);
      const safeLimit = !isNaN(limitVal) && limitVal > 0 ? limitVal : 1;
      const budgetUtilization = (currentPeriodSpend / safeLimit) * 100;

      const budgetProgress = budgets.map(b => {
          const spent = transactions
            .filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
            .reduce((sum, t) => sum + t.amount, 0);
          return { ...b, spent, percentage: Math.min((spent / b.limit) * 100, 100) };
      });

      // Total Savings calculation
      const totalTarget = goals.reduce((acc, g) => acc + g.targetAmount, 0);
      const totalSaved = goals.reduce((acc, g) => acc + g.currentAmount, 0);
      const savingsProgress = totalTarget > 0 ? (totalSaved / totalTarget) * 100 : 0;

      return { budgetUtilization, budgetProgress, totalTarget, totalSaved, savingsProgress };
  }, [currentPeriodSpend, spendingLimit, budgets, transactions, currentMonth, goals]);

  const neuralCapacity = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
  const neuralRemaining = Math.max(0, neuralCapacity - insightUsage);
  const safeName = userName && userName.trim() !== '' ? userName : 'Pilot';
  const displayLimit = spendingLimit && !isNaN(Number(spendingLimit)) ? Number(spendingLimit) : 0;

  const handleProceedWithScan = () => {
    setShowScanConfirm(false);
    onNavigate('insights', { reportType: 'daily' });
  };

  // Find a specific budget for the Goal Vector card
  const highlightedBudget = budgets.find(b => b.category === 'Entertainment') || budgets[0];
  const highlightedBudgetMetrics = highlightedBudget 
      ? goalMetrics.budgetProgress.find(b => b.id === highlightedBudget.id) 
      : null;

  const displayGoals = goals.slice(0, 2);

  return (
    <div className="pb-20 px-2 md:px-0">

        {/* Header */}
        <div className="mb-6 mt-2 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div>
                <h1 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tight">Good {dayName}, {safeName}</h1>
                <div className="flex items-center gap-2 mt-1">
                    <span className="flex h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">
                        Last Updated: {lastUpdated}
                    </p>
                </div>
            </div>

            {onAddTransaction && (
                <button 
                    onClick={onAddTransaction}
                    className="hidden md:flex items-center gap-2 bg-white/5 hover:bg-white/10 backdrop-blur-md border border-white/10 text-white px-5 py-3 rounded-2xl text-xs font-black uppercase tracking-widest shadow-lg hover:shadow-xl active:scale-95 transition-all group"
                >
                    <Plus className="w-4 h-4 group-hover:rotate-90 transition-transform" />
                    <span>Make New Transaction</span>
                </button>
            )}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            {/* LEFT MAIN PANEL */}
            <div className="lg:col-span-8 flex flex-col gap-6 h-full">

                {/* 1. New Command Grid (Moved from right sidebar + consolidated stats) */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    {/* Net Worth */}
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-between h-32 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><Wallet className="w-12 h-12 text-blue-500" /></div>
                        <div className="flex items-center gap-2 mb-2 relative z-10">
                            <div className="p-1.5 rounded-lg bg-blue-500/10"><Wallet className="w-4 h-4 text-blue-500" /></div>
                            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Net Worth</span>
                        </div>
                        <div className="text-2xl font-black text-white tracking-tight relative z-10">{formatCurrency(netWorth)}</div>
                    </div>

                    {/* Credit Card */}
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-between h-32 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><CreditCard className="w-12 h-12 text-rose-500" /></div>
                        <div className="flex items-center gap-2 mb-2 relative z-10">
                            <div className="p-1.5 rounded-lg bg-rose-500/10"><CreditCard className="w-4 h-4 text-rose-500" /></div>
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Debt</span>
                            </div>
                        </div>
                        <div className="text-2xl font-black text-white tracking-tight relative z-10">{formatCurrency(creditCardDebt)}</div>
                    </div>

                    {/* Burn Rate */}
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-between h-32 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><Flame className="w-12 h-12 text-orange-500" /></div>
                        <div className="flex items-center gap-2 mb-2 relative z-10">
                            <div className="p-1.5 rounded-lg bg-orange-500/10"><Flame className="w-4 h-4 text-orange-500" /></div>
                            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Daily Burn</span>
                        </div>
                        <div className="text-2xl font-black text-white tracking-tight relative z-10">{formatCurrency(stats.currentDailyAvg)}</div>
                    </div>

                    {/* Neural Capacity */}
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-between h-32 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><Zap className="w-12 h-12 text-purple-500" /></div>
                        <div className="flex items-center gap-2 mb-2 relative z-10">
                            <div className="p-1.5 rounded-lg bg-purple-500/10"><Zap className="w-4 h-4 text-purple-500" /></div>
                            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Capacity</span>
                        </div>
                        <div className="text-2xl font-black text-white tracking-tight relative z-10">{neuralRemaining} <span className="text-sm text-slate-500 font-bold">OPS</span></div>
                    </div>
                </div>

                {/* 2. Spending chart */}
                <div className="glass-card p-6 md:p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 backdrop-blur-xl relative overflow-hidden flex flex-col md:flex-row items-center gap-8 min-h-[300px]">
                    <div className="w-48 h-48 md:w-56 md:h-56 relative shrink-0 flex items-center justify-center">
                        {expenditureData.isEmpty ? (
                            <div className="text-center">
                                <div className="w-40 h-40 rounded-full border-2 border-dashed border-indigo-500/30 flex items-center justify-center animate-pulse">
                                    <PieChartIcon className="w-10 h-10 text-indigo-500/50" />
                                </div>
                            </div>
                        ) : (
                            <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie
                                        data={expenditureData.chartData}
                                        cx="50%"
                                        cy="50%"
                                        innerRadius={60}
                                        outerRadius={90}
                                        paddingAngle={2}
                                        dataKey="value"
                                        stroke="none"
                                    >
                                        {expenditureData.chartData.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                        ))}
                                    </Pie>
                                    <Tooltip 
                                        contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px', padding: '8px' }} 
                                        itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }} 
                                        formatter={(v: number) => formatCurrency(v)} 
                                    />
                                </PieChart>
                            </ResponsiveContainer>
                        )}
                    </div>

                    <div className="flex-1 w-full">
                        <div className="flex justify-between items-start mb-6">
                            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                <AlignLeft className="w-4 h-4 text-indigo-500" />
                                Spending chart
                            </h3>
                        </div>

                        {expenditureData.topCategory ? (
                            <div className="mb-6 p-4 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-between">
                                <div>
                                    <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest block mb-1">Primary Drain</span>
                                    <span className="text-lg font-bold text-white">{expenditureData.topCategory.name}</span>
                                </div>
                                <div className="text-right">
                                    <span className="text-xl font-black text-white">{formatCurrency(expenditureData.topCategory.value)}</span>
                                    <span className="text-[10px] font-bold text-slate-400 block">{((expenditureData.topCategory.value / expenditureData.total) * 100).toFixed(1)}%</span>
                                </div>
                            </div>
                        ) : (
                            <div className="mb-6 p-6 rounded-2xl bg-slate-900/50 border border-white/5 flex flex-col justify-center items-start text-left">
                                <h4 className="text-white font-bold text-sm mb-1">Sensors Inactive</h4>
                                <p className="text-slate-500 text-xs font-medium mb-3">Log expense data to initialize topology map.</p>
                                <button onClick={onAddTransaction} className="text-indigo-400 font-bold text-xs uppercase tracking-widest hover:text-indigo-300 transition-colors flex items-center gap-1">
                                    Initialize <ChevronDown className="w-3 h-3 -rotate-90" />
                                </button>
                            </div>
                        )}

                        <div className="space-y-3">
                            {!expenditureData.isEmpty && expenditureData.chartData.slice(0, 3).map((item, i) => (
                                <div key={i} className="flex items-center justify-between group">
                                    <div className="flex items-center gap-3">
                                        <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                                        <span className="text-xs font-bold text-slate-300 group-hover:text-white transition-colors">{item.name}</span>
                                    </div>
                                    <div className="h-1 flex-1 mx-4 bg-slate-800/50 rounded-full overflow-hidden">
                                        <div className="h-full rounded-full transition-all duration-1000" style={{ width: `${(item.value / expenditureData.total) * 60}%`, backgroundColor: COLORS[i % COLORS.length], opacity: 0.6 }}></div>
                                    </div>
                                    <span className="text-[10px] font-bold text-slate-500">MTD</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* 3. Full Width Transactions */}
                <div className="glass-card rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 p-6 overflow-hidden flex flex-col">
                    <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">My Recent Transactions</h3>
                    <div className="flex-1 w-full">
                        {recentTransactions.length > 0 ? (
                            <table className="w-full text-left border-collapse">
                                <thead className="text-[9px] font-black text-slate-500 uppercase tracking-widest border-b border-white/5">
                                    <tr>
                                        <th className="py-2">Date</th>
                                        <th className="py-2">Name</th>
                                        <th className="py-2 text-right">Amount</th>
                                    </tr>
                                </thead>
                                <tbody className="text-xs font-bold text-slate-300">
                                    {recentTransactions.map((t) => (
                                        <tr key={t.id} className="border-b border-white/5 last:border-0 hover:bg-white/5 transition-colors">
                                            <td className="py-4 text-slate-500 font-mono text-[10px]">{new Date(t.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }).toUpperCase()}</td>
                                            <td className="py-4">{t.merchant}</td>
                                            <td className={`py-4 text-right ${t.type === TransactionType.INCOME ? 'text-emerald-400' : 'text-white'}`}>{formatCurrency(t.amount)}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center p-6 bg-slate-900/30 rounded-2xl border-2 border-dashed border-white/5">
                                <div className="w-12 h-12 bg-slate-800 rounded-full flex items-center justify-center mb-3">
                                    <Rocket className="w-6 h-6 text-indigo-400" />
                                </div>
                                <h4 className="text-white font-bold text-sm">Mission: First Log</h4>
                                <p className="text-slate-500 text-[10px] uppercase tracking-wider mb-4">Ledger is empty.</p>
