  };

  const handleIncrementUsage = (type: 'insight' | 'scan' | 'negotiation', amount = 1) => {
      const key = `nova_${type}_usage`;
      const now = new Date();
      const current = type === 'insight' ? insightUsage : type === 'scan' ? scanUsage : negotiationUsage;
