import React, { useState, useEffect, useRef } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot, SuggestedAction, GoalProposal, DailyReport, MonthlyReport, ReportType } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { generateDailyReport, generateMonthlyReport } from '../services/reportEngine';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Send, Lock, Sparkles, RefreshCw, Zap, Crown, Target, Calendar, ChevronRight, Check, Activity, BarChart3, MessageSquare, ArrowUpRight } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode;
  onNavigate: (tab: string) => void;
  onAddGoal?: (goal: Goal) => void;
  autoScanTriggered?: boolean;
  activeReport?: ReportType;
  spendingLimit?: number;
}

const Insights: React.FC<InsightsProps> = ({ 
    transactions, 
    goals, 
    budgets, 
    userPlan, 
    onUpgradeClick, 
    formatCurrency, 
    initialPrompt, 
    onPromptHandled, 
    onApplyBudgets, 
    insightUsage, 
    onIncrementUsage, 
    botMode, 
    onNavigate, 
    onAddGoal,
    autoScanTriggered = false,
    activeReport,
    spendingLimit = 1000
}) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'I am connected. Auditing financial vectors. State your query or request a report.' 
            : 'Hello! I\'m here to help you optimize your financial wellness. How can I assist you today?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);

  // Dedicated Report State
  const [activeView, setActiveView] = useState<'idle' | 'daily' | 'monthly' | 'ai'>('idle');
  const [dailyReport, setDailyReport] = useState<DailyReport | null>(null);
  const [monthlyReport, setMonthlyReport] = useState<MonthlyReport | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isPro = userPlan === 'pro';
  const currentLimit = isUltra ? 1500 : isPro ? 50 : 3;
  const isLocked = insightUsage >= currentLimit;

  // Handle activeReport trigger from external nav
  useEffect(() => {
      if (activeReport === 'daily') {
          handleGenerateDaily();
      } else if (activeReport === 'monthly') {
          handleGenerateMonthly();
      }
  }, [activeReport, transactions, spendingLimit]);

  // Initial Prompt Handler
  useEffect(() => {
      if (initialPrompt && onPromptHandled) {
          handleSendMessage(null, initialPrompt);
          onPromptHandled();
      }
  }, [initialPrompt]);

  const handleGenerateDaily = () => {
      const report = generateDailyReport(transactions, spendingLimit || 1000);
      setDailyReport(report);
      setActiveView('daily');
  };

  const handleGenerateMonthly = () => {
      const report = generateMonthlyReport(transactions, spendingLimit || 1000);
      setMonthlyReport(report);
      setActiveView('monthly');
  };

  const runAnalysis = async () => {
    if (isLocked || loading) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    setActiveView('ai'); // Switch view immediately to show loading there

    try {
      const result = await analyzeFinancialData(transactions, userPlan);
      if (result) setAnalysis(result);
      else setError("Coach is analyzing other portfolios. Try again.");
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (autoScanTriggered && !analysis && !loading && !isLocked) {
        runAnalysis();
    }
  }, [autoScanTriggered, analysis, loading, isLocked]);

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: Date.now().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${Date.now()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount,
              startDate: new Date().toISOString()
          }]);
      }
      if (analysis) setAnalysis({ ...analysis, goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id) });
  };

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10),
        activeGoals: goals,
        budgets: budgets
    };

    try {
        const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode, userPlan);
        setChatHistory(prev => [...prev, { 
            id: (Date.now() + 1).toString(), 
            role: 'assistant', 
            content: response.message, 
            timestamp: new Date(),
            sentiment: response.sentiment as any,
            suggestedActions: response.suggestedActions
        }]);
    } catch (err) {
        setChatHistory(prev => [...prev, {
            id: (Date.now() + 1).toString(),
            role: 'assistant',
            content: "I'm having trouble connecting to the analysis core right now. Please try again in a moment.",
            timestamp: new Date(),
            sentiment: 'critical'
        }]);
    } finally {
        setChatLoading(false);
    }
  };

  const handleActionClick = (action: SuggestedAction) => {
    if (action.actionId.startsWith('navigate_')) {
        const tab = action.actionId.replace('navigate_', '');
        onNavigate(tab);
    } else if (action.actionId === 'chat_prompt' && action.payload) {
        handleSendMessage(null, action.payload);
    }
  };

  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory, chatLoading]);

  // --- SUB-COMPONENTS ---

  const RiskGauge = ({ score }: { score: number }) => {
      const color = score >= 60 ? '#f43f5e' : score >= 30 ? '#f59e0b' : '#10b981';
      return (
          <div className="relative w-20 h-20 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90">
                  <circle cx="40" cy="40" r="32" stroke="#1e293b" strokeWidth="6" fill="transparent" />
                  <circle cx="40" cy="40" r="32" stroke={color} strokeWidth="6" fill="transparent" strokeDasharray={201} strokeDashoffset={201 - (score / 100) * 201} strokeLinecap="round" />
              </svg>
              <div className="absolute flex flex-col items-center">
                  <span className="text-xl font-black text-white">{score}</span>
                  <span className="text-[7px] font-bold uppercase tracking-widest text-slate-500">Risk</span>
              </div>
          </div>
      );
  };

  const HealthGauge = ({ score }: { score: number }) => {
      const color = score >= 80 ? '#10b981' : score >= 50 ? '#f59e0b' : '#f43f5e';
      return (
          <div className="relative w-20 h-20 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90">
                  <circle cx="40" cy="40" r="32" stroke="#1e293b" strokeWidth="6" fill="transparent" />
                  <circle cx="40" cy="40" r="32" stroke={color} strokeWidth="6" fill="transparent" strokeDasharray={201} strokeDashoffset={201 - (score / 100) * 201} strokeLinecap="round" />
              </svg>
              <div className="absolute flex flex-col items-center">
                  <span className="text-xl font-black text-white">{score}</span>
                  <span className="text-[7px] font-bold uppercase tracking-widest text-slate-500">Health</span>
              </div>
          </div>
      );
  };

  const renderDailyReport = () => {
      if (!dailyReport) return null;
      return (
          <div className="space-y-6 animate-slide-up pb-6">
              <div className="flex items-center justify-between">
                  <div>
                      <h3 className="text-xl font-bold text-white mb-1">Daily Brief</h3>
                      <p className="text-slate-400 text-xs">{new Date(dailyReport.date).toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}</p>
                  </div>
                  <RiskGauge score={dailyReport.riskScore} />
              </div>

              <div className="grid grid-cols-2 gap-3">
                  <div className="p-4 bg-slate-900 rounded-2xl border border-white/5">
                      <p className="text-slate-500 text-[9px] font-bold uppercase tracking-wider mb-1">24h Spending</p>
                      <p className="text-xl font-black text-white">{formatCurrency(dailyReport.totals.expense)}</p>
                  </div>
                  <div className="p-4 bg-slate-900 rounded-2xl border border-white/5">
                      <p className="text-slate-500 text-[9px] font-bold uppercase tracking-wider mb-1">Momentum</p>
                      <p className={`text-xl font-black ${dailyReport.metrics.momentumDelta > 0.1 ? 'text-rose-400' : 'text-emerald-400'}`}>
                          {dailyReport.metrics.momentumDelta > 0 ? '+' : ''}{(dailyReport.metrics.momentumDelta * 100).toFixed(0)}%
                      </p>
                  </div>
              </div>

              <div className="bg-indigo-600/10 p-5 rounded-2xl border border-indigo-500/20">
                  <div className="flex items-center gap-2 mb-2">
                      <Target className="w-4 h-4 text-indigo-400" />
                      <span className="text-[10px] font-bold uppercase tracking-widest text-indigo-300">Action Item</span>
                  </div>
                  <p className="text-sm font-bold text-white leading-tight">{dailyReport.action.text}</p>
              </div>

              <div className="space-y-2">
                  <h4 className="text-slate-500 text-[10px] font-bold uppercase tracking-wider px-1">Signals</h4>
                  {dailyReport.signals.map((sig, idx) => (
                      <div key={idx} className="flex gap-3 p-3 bg-slate-900 rounded-xl border border-white/5 items-start">
                          {sig.type === 'stable' ? <CheckCircle className="w-4 h-4 text-emerald-500 shrink-0 mt-0.5" /> : <AlertTriangle className="w-4 h-4 text-amber-500 shrink-0 mt-0.5" />}
                          <div>
                              <p className="text-xs font-bold text-slate-300">{sig.title}</p>
                              <p className="text-[10px] text-slate-500 mt-0.5">{sig.description}</p>
                          </div>
                      </div>
                  ))}
              </div>
          </div>
      );
  };

  const renderMonthlyReport = () => {
      if (!monthlyReport) return null;
      return (
          <div className="space-y-6 animate-slide-up pb-6">
              <div className="flex items-center justify-between">
                  <div>
                      <h3 className="text-xl font-bold text-white mb-1">Monthly Audit</h3>
                      <p className="text-slate-400 text-xs">{monthlyReport.month}</p>
                  </div>
                  <HealthGauge score={monthlyReport.healthScore} />
              </div>

              <div className="grid grid-cols-3 gap-2">
                  <div className="p-3 bg-slate-900 rounded-xl border border-white/5 text-center">
                      <p className="text-slate-500 text-[8px] font-bold uppercase tracking-wider mb-1">Savings Rate</p>
                      <p className={`text-base font-black ${monthlyReport.metrics.savingsPowerIndex > 0.1 ? 'text-emerald-400' : 'text-rose-400'}`}>{(monthlyReport.metrics.savingsPowerIndex * 100).toFixed(0)}%</p>
                  </div>
                  <div className="p-3 bg-slate-900 rounded-xl border border-white/5 text-center">
                      <p className="text-slate-500 text-[8px] font-bold uppercase tracking-wider mb-1">Fixed Load</p>
                      <p className="text-base font-black text-white">{(monthlyReport.metrics.expenseLoadRatio * 100).toFixed(0)}%</p>
                  </div>
                  <div className="p-3 bg-slate-900 rounded-xl border border-white/5 text-center">
                      <p className="text-slate-500 text-[8px] font-bold uppercase tracking-wider mb-1">Risk Factor</p>
                      <p className={`text-base font-black ${monthlyReport.riskScore > 50 ? 'text-rose-400' : 'text-emerald-400'}`}>{monthlyReport.riskScore.toFixed(0)}</p>
                  </div>
              </div>

              <div className="bg-slate-900 p-5 rounded-2xl border border-indigo-500/20 relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-4 opacity-5"><Crown className="w-16 h-16" /></div>
                  <h4 className="text-indigo-400 text-[10px] font-bold uppercase tracking-widest mb-2 flex items-center gap-2"><Sparkles className="w-3 h-3" /> Strategic Objective</h4>
                  <p className="text-base font-bold text-white mb-3 leading-tight">{monthlyReport.strategicPlan.objective}</p>
                  <ul className="space-y-2">
                      {monthlyReport.strategicPlan.actions.map((act, i) => (
                          <li key={i} className="flex items-start gap-2 text-xs text-slate-400">
                              <span className="w-4 h-4 rounded-full bg-indigo-500/20 text-indigo-400 flex items-center justify-center text-[10px] font-bold shrink-0 mt-0.5">{i+1}</span>
                              {act}
                          </li>
                      ))}
                  </ul>
              </div>

              <div className="space-y-2">
                  <h4 className="text-slate-500 text-[10px] font-bold uppercase tracking-wider px-1">Key Issues</h4>
                  {monthlyReport.problems.map((prob, idx) => (
                      <div key={idx} className="flex items-center gap-3 p-3 bg-slate-900 rounded-xl border border-white/5">
                          <div className={`w-1.5 h-1.5 rounded-full ${prob.severity === 'high' ? 'bg-rose-500' : prob.severity === 'medium' ? 'bg-amber-500' : 'bg-blue-500'}`}></div>
                          <p className="text-xs font-medium text-slate-300">{prob.title}</p>
