                  </div>
                  <h3 className="text-base font-bold text-white mb-2">Analyzing Matrix...</h3>
                  <p className="text-slate-500 text-xs uppercase tracking-widest">Processing Vectors</p>
              </div>
          );
      }
      if (!analysis) return null;

      return (
          <div className="space-y-6 animate-slide-up pb-6">
              <div className="flex items-center justify-between">
                  <div>
                      <h3 className="text-xl font-bold text-white mb-1">Deep Scan</h3>
