                  </div>
                  <RiskGauge score={analysis.risk_score} />
              </div>

              <div className="p-5 bg-slate-900 rounded-2xl border border-white/5 flex items-center justify-between">
                  <div>
                      <p className="text-slate-500 text-[10px] font-bold uppercase tracking-wider mb-1">Predicted Spend (30d)</p>
