                  </div>
                  <div className="p-3 bg-slate-800 rounded-xl">
                      <TrendingUp className="w-5 h-5 text-indigo-400" />
                  </div>
              </div>

              <div className="space-y-3">
                  <h4 className="text-slate-500 text-[10px] font-bold uppercase tracking-wider px-1">Insights</h4>
