                          <div className="flex items-center gap-2 mb-1">
                              {insight.type === 'success' && <CheckCircle className="w-3 h-3 text-emerald-400" />}
                              {insight.type === 'warning' && <AlertTriangle className="w-3 h-3 text-amber-400" />}
                              {insight.type === 'critical' && <ShieldAlert className="w-3 h-3 text-rose-400" />}
                              {insight.type === 'info' && <Info className="w-3 h-3 text-blue-400" />}
                              <span className="text-xs font-bold text-white">{insight.title}</span>
                          </div>
                          <p className="text-xs text-slate-400 leading-relaxed">{insight.description}</p>
