              {analysis.goal_proposals && analysis.goal_proposals.length > 0 && (
                  <div className="bg-slate-900 p-5 rounded-2xl border border-emerald-500/20">
                      <h4 className="text-emerald-400 text-[10px] font-bold uppercase tracking-widest mb-3 flex items-center gap-2"><Sparkles className="w-3 h-3" /> Opportunity</h4>
                      {analysis.goal_proposals.map((proposal) => (
                          <div key={proposal.id} className="space-y-3">
