  return (
    <div className="h-[calc(100vh-8rem)] flex flex-col md:flex-row gap-6 overflow-hidden">
        {isLocked && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm">
                <div className="bg-slate-900 border border-white/10 p-8 rounded-3xl max-w-sm text-center shadow-2xl">
                    <div className="w-16 h-16 bg-gradient-to-tr from-indigo-500 to-purple-500 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-lg">
                        <Lock className="w-8 h-8 text-white" />
                    </div>
                    <h3 className="text-xl font-bold text-white mb-2">Usage Limit Reached</h3>
                    <p className="text-slate-400 text-sm mb-6">You've used all {currentLimit} free AI analyses for this cycle. Upgrade to Elite for unlimited access.</p>
                    <button onClick={onUpgradeClick} className="w-full py-3 bg-white text-slate-900 font-bold rounded-xl hover:scale-105 transition-all">Upgrade Now</button>
                </div>
            </div>
        )}

        {/* Left Panel: Reports & Actions (Modernized) */}
        <div className="w-full md:w-1/3 flex flex-col gap-4 overflow-hidden">
            <div className="shrink-0 flex items-center justify-between mb-2">
                <h2 className="text-lg font-black text-white tracking-tight flex items-center gap-2">
                    <Bot className="w-5 h-5 text-indigo-500" /> Neural Coach
                </h2>
                <div className="px-2 py-0.5 bg-slate-800 rounded border border-white/5 text-[9px] font-bold text-slate-400">
                    {insightUsage} / {currentLimit} OPS
                </div>
            </div>

            <div className="grid grid-cols-3 gap-2 shrink-0">
                <button 
                    onClick={handleGenerateDaily}
                    className={`p-3 rounded-xl border transition-all text-center flex flex-col items-center justify-center gap-2 group ${activeView === 'daily' ? 'bg-white text-slate-900 border-white' : 'bg-slate-900/50 text-slate-400 border-white/5 hover:bg-slate-800 hover:text-white'}`}
                >
                    <Zap className={`w-4 h-4 ${activeView === 'daily' ? 'text-slate-900' : 'text-indigo-400'}`} />
                    <span className="text-[10px] font-bold uppercase tracking-wide">Daily</span>
                </button>
                <button 
                    onClick={handleGenerateMonthly}
                    className={`p-3 rounded-xl border transition-all text-center flex flex-col items-center justify-center gap-2 group ${activeView === 'monthly' ? 'bg-white text-slate-900 border-white' : 'bg-slate-900/50 text-slate-400 border-white/5 hover:bg-slate-800 hover:text-white'}`}
                >
                    <Calendar className={`w-4 h-4 ${activeView === 'monthly' ? 'text-slate-900' : 'text-amber-400'}`} />
                    <span className="text-[10px] font-bold uppercase tracking-wide">Monthly</span>
                </button>
                <button 
                    onClick={runAnalysis}
                    disabled={loading}
                    className={`p-3 rounded-xl border transition-all text-center flex flex-col items-center justify-center gap-2 group ${activeView === 'ai' ? 'bg-white text-slate-900 border-white' : 'bg-slate-900/50 text-slate-400 border-white/5 hover:bg-slate-800 hover:text-white'}`}
                >
                    {loading ? <RefreshCw className="w-4 h-4 animate-spin text-slate-900" /> : <BrainCircuit className={`w-4 h-4 ${activeView === 'ai' ? 'text-slate-900' : 'text-emerald-400'}`} />}
                    <span className="text-[10px] font-bold uppercase tracking-wide">AI Scan</span>
                </button>
            </div>

            <div className="flex-1 bg-slate-950/30 rounded-3xl border border-white/5 p-5 overflow-y-auto custom-scrollbar relative">
                {activeView === 'idle' && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center text-center opacity-30 p-6">
                        <Activity className="w-12 h-12 text-slate-500 mb-3" />
                        <p className="text-xs font-bold text-slate-400">Select a protocol to initialize analysis.</p>
                    </div>
                )}
                {activeView === 'daily' && renderDailyReport()}
                {activeView === 'monthly' && renderMonthlyReport()}
                {activeView === 'ai' && renderAiAnalysis()}
            </div>
        </div>

        {/* Right Panel: Chat Interface (Modernized) */}
        <div className="flex-1 bg-[#0f172a] rounded-3xl border border-white/5 flex flex-col overflow-hidden relative shadow-2xl">
            {/* Chat Header */}
            <div className="p-4 border-b border-white/5 bg-slate-900/50 backdrop-blur-md flex justify-between items-center z-10">
                <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-gradient-to-tr from-indigo-600 to-violet-600 rounded-lg flex items-center justify-center shadow-lg">
                        <MessageSquare className="w-4 h-4 text-white" />
                    </div>
                    <div>
                        <h3 className="font-bold text-white text-sm">Assistant</h3>
                        <div className="flex items-center gap-1.5">
                            <span className={`w-1.5 h-1.5 rounded-full ${botMode === 'ruthless' ? 'bg-rose-500' : 'bg-emerald-500'}`}></span>
                            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">{botMode} Mode</span>
                        </div>
                    </div>
                </div>
                <button 
                    onClick={() => setChatHistory([])}
                    className="p-2 hover:bg-white/5 rounded-lg text-slate-500 hover:text-white transition-colors"
                    title="Clear Chat"
                >
                    <RefreshCcw className="w-4 h-4" />
                </button>
            </div>

            {/* Chat Messages Area */}
            <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
                {chatHistory.length === 0 && (
                    <div className="h-full flex flex-col items-center justify-center opacity-20">
                        <Bot className="w-16 h-16 text-slate-500 mb-4" />
                        <p className="text-sm font-bold text-slate-500">System Ready.</p>
                    </div>
                )}
                {chatHistory.map((msg) => (
                    <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-slide-up group`}>
                        <div className={`max-w-[85%] md:max-w-[75%] p-4 rounded-2xl text-sm font-medium leading-relaxed shadow-sm relative ${
                            msg.role === 'user' 
                                ? 'bg-indigo-600 text-white rounded-br-sm' 
                                : 'bg-slate-800 text-slate-200 rounded-bl-sm border border-white/5'
                        }`}>
                            {msg.content}
                            {/* Tiny timestamp outside bubble for cleaner look on hover? Or inside. Inside is safer. */}
                        </div>

                        {msg.suggestedActions && (
                            <div className="flex flex-wrap gap-2 mt-3 justify-start max-w-[90%]">
                                {msg.suggestedActions.map((action, idx) => (
                                    <button 
                                        key={idx} 
                                        onClick={() => handleActionClick(action)} 
                                        className="flex items-center gap-1.5 px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-indigo-300 hover:text-indigo-200 text-[10px] font-bold uppercase tracking-wider rounded-lg border border-white/5 transition-all shadow-sm"
                                    >
                                        {action.label} <ArrowUpRight className="w-3 h-3" />
                                    </button>
                                ))}
                            </div>
                        )}
                        <span className={`text-[9px] text-slate-600 font-bold mt-1.5 px-1 opacity-0 group-hover:opacity-100 transition-opacity`}>
                            {msg.timestamp.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}
                        </span>
                    </div>
                ))}
                {chatLoading && (
                    <div className="flex items-center gap-1 p-4 bg-slate-800/50 rounded-2xl rounded-bl-none w-fit border border-white/5">
                        <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce"></div>
                        <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce delay-100"></div>
                        <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce delay-200"></div>
                    </div>
                )}
                <div ref={chatEndRef} />
            </div>

            {/* Input Area */}
            <div className="p-4 bg-slate-900 border-t border-white/5 relative z-20">
                <form onSubmit={handleSendMessage} className="relative flex items-center gap-2">
                    <input 
                        type="text" 
                        value={chatInput} 
                        onChange={(e) => setChatInput(e.target.value)} 
                        placeholder="Type a command or query..." 
                        className="flex-1 bg-slate-950 border border-white/10 rounded-xl pl-4 pr-12 py-3.5 text-sm text-white focus:outline-none focus:border-indigo-500 transition-all placeholder:text-slate-600 font-medium"
                    />
                    <button 
                        type="submit" 
                        disabled={!chatInput.trim() || chatLoading} 
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg transition-all disabled:opacity-50 shadow-lg active:scale-95"
                    >
                        <Send className="w-4 h-4" />
                    </button>
                </form>
            </div>
        </div>
    </div>
  );
};

export default Insights;

